{
  "name": "@lunchbox-labs/prompt-composer-core",
  "private": true,
  "version": "0.3.0",
  "description": "Internal source shared by the OpenCode and Kilo CLI Prompt Composer packages",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lunchbox-labs/prompt-composer-plugin.git",
    "directory": "packages/core"
  },
  "engines": {
    "node": ">=22.18.0"
  },
  "exports": {
    "./host": "./src/host.ts",
    "./server": "./src/server.ts",
    "./tui": "./src/tui.ts",
    "./includes": "./src/includes.ts"
  },
  "scripts": {
    "typecheck": "tsc -p tsconfig.json",
    "test": "node --experimental-strip-types --test tests/*.test.ts"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.19.5",
    "@opencode-ai/sdk": "1.19.5",
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  }
}

{
  "name": "@lunchbox-labs/kilo-prompt-composer",
  "version": "0.3.0",
  "description": "Compose reusable prompt text in native Kilo CLI agents, commands and on-demand skills",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lunchbox-labs/prompt-composer-plugin.git",
    "directory": "packages/kilo"
  },
  "engines": {
    "node": ">=22.18.0"
  },
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "default": "./dist/server.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "default": "./dist/server.js"
    },
    "./includes": {
      "types": "./dist/includes.d.ts",
      "default": "./dist/includes.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "docs/examples",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsdown --config ../../tsdown.config.mjs",
    "typecheck": "tsc -p tsconfig.json && tsc -p tsconfig.core.json",
    "prepack": "npm run build"
  },
  "devDependencies": {
    "@kilocode/plugin": "7.8.27",
    "@kilocode/sdk": "7.8.27",
    "@opentui/core": "0.5.11",
    "@opentui/keymap": "0.5.11",
    "@opentui/solid": "0.5.11",
    "solid-js": "1.9.12"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  }
}

